    public static string Get(string? key) =>
        key is not null && Regular.TryGetValue(key, out var d) ? d : string.Empty;

    public static string GetFilled(string? key) =>
        key is not null && Filled.TryGetValue(key, out var d) ? d : Get(key);

    // A genre name -> its tile icon key (Search genre grid).
    public static string ForGenre(string? genre) => genre switch
    {
        "Action" => "genre_action",
        "Drama" => "genre_drama",
        "Sci-Fi" => "genre_scifi",
        "Horror" => "genre_horror",
        "Comedy" => "genre_comedy",
        "Documentary" => "genre_documentary",
        "Thriller" => "genre_thriller",
        "Romance" => "genre_romance",
        _ => "genre_drama",
    };

    // A settings-row label -> its leading icon key (Profile settings groups).
    public static string ForSetting(string? label) => label switch
    {
        "Video Quality" => "video_quality",
        "Audio Language" => "audio",
        "Subtitles" => "subtitles",
        "Autoplay Next Episode" => "autoplay",
        "Download Quality" => "download_quality",
        "Storage Location" => "storage",
        "Download Over Wi-Fi Only" => "wifi",
        "Manage Subscription" => "subscription",
        "Edit Profile" => "edit_profile",
        "Privacy Settings" => "privacy",
        "Notifications" => "notifications",
        "Help Center" => "help",
        "Send Feedback" => "feedback",
        "About CineStream" => "about",
        _ => "chevron",
    };
}
